import {renderSkillPixelIcon} from './skill-pixel-icons.js';
import {SKILL_TREE_DESCRIPTIONS} from './skill-tree-descriptions.js';
import {SKILL_TREE_DEFINITION as D} from './skill-tree-definition.js';
import {normalizeSkillTree,skillPointBudget,skillPresetCost,validSkillTree} from './skill-tree-state.js';
import {icon} from './icons.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=ids=>ids.map(id=>D.nodes.find(n=>n.id===id)?.name??id).join('、');
const choices=[['always','可用即施放'],['low','生命低于60%'],['charge','敌人将重击'],['burn','目标已灼烧']];
const groups=[
 {id:'steel',name:'裂岩战技',ids:['fracture_strike','fault_sweep','breach_followup','axe_fervor','hammer_penetration']},
 {id:'fire',name:'炉火战技',ids:['ember_brand','furnace_wave','cinder_barrage','fire_affinity']},
 {id:'guard',name:'守势战技',ids:['iron_vigil','bastion_blow','repelling_wave','shield_reserve']},
 {id:'shared',name:'共通战技',ids:['anvil_cry','breaking_intercept','furnace_etch','scatter_ash','forge_breath','purifying_bulwark','mountain_vitality','forged_resilience']}
];
const treeFingerprint=s=>JSON.stringify({skillTree:s.skillTree,skills:s.skills,conditions:s.conditions,loadouts:s.loadouts});
export function renderSkillTree(m){
 const p=m.draft.skillTree.presets[m.index],budget=skillPointBudget(m.draft),spent=skillPresetCost(p,D),blocked=m.busy;
 const status=m.conflict?'配置已在其他位置变化，请取消草稿后重新编辑。':m.error||(m.blocked?'可预先加点；结束当前战斗并停止远征后确认应用。':budget===0?'升级获得技能点。初始普通攻击无需解锁。':'点击技能解锁，确认应用后生效。');
 const commitButton=()=>`<button class="primary" data-tree-action="commit" ${blocked||m.blocked||m.conflict||m.refund?'disabled':''}>${m.busy?'正在保存…':'确认应用'}</button>`;
 const card=id=>{const n=D.nodes.find(n=>n.id===id),learned=p.unlocked.includes(id),missing=n.requires.filter(key=>!p.unlocked.includes(key)),affordable=spent+n.cost<=budget,available=!missing.length&&affordable,description=SKILL_TREE_DESCRIPTIONS[id];const reason=learned?'点击退还技能点':missing.length?'需先学习 '+names(missing):!affordable?`还需 ${spent+n.cost-budget} 点`:'点击解锁';return `<article class="treeNodeCard" data-tree-branch-node="${id}"><button class="treeNode ${learned?'learned':''}" data-tree-action="node" data-tree-id="${id}" ${blocked||m.conflict||!learned&&!available?'disabled':''} aria-pressed="${learned}" aria-label="${esc(n.name)} · ${learned?'已学习':'未学习'} · ${esc(reason)}" title="${esc(reason)}"><span class="treeNodeArt">${renderSkillPixelIcon(id)}${!learned?'<span class="skillPixelLock" aria-hidden="true"></span>':''}</span><strong>${esc(n.name)}</strong><small>${n.kind==='passive'?'被动':'主动'} · ${n.cost}点</small><small class="treeNodeAction">${learned?'已学习 · 退还':available?'＋ 解锁':esc(reason)}</small></button>${n.requires.length?`<div class="treePrerequisite">前置：${esc(names(n.requires))}</div>`:''}<details class="treeSkillDescription"><summary>技能效果</summary>${[description?.base,description?.axe,description?.hammer].filter(Boolean).map(text=>`<p>${esc(text)}</p>`).join('')}${n.kind==='passive'?'<p>仅装入两个被动槽之一后生效。</p>':''}</details></article>`;};
 return `<section class="skillTreeEditor"><header><div><h2>战技树 · 方案${m.index+1}</h2><span>已用 ${spent} / ${budget} 点 · 全树99点</span></div><strong class="treePointBalance">剩余 ${budget-spent} 点</strong>${commitButton()}</header><div class="treeStatusBar"><p class="treeStatus" role="status">${esc(status)}</p>${m.blocked&&m.draft.running?`<button data-stopafter="1" ${m.busy||m.stopRequested?'disabled':''}>${m.stopRequested?'等待本次挑战结束':m.inDungeon?'本次副本结束后停止':'本场结束后停止'}</button>`:''}</div><nav>${m.draft.skillTree.presets.map((q,i)=>`<button data-tree-action="plan" data-tree-id="${i}" aria-pressed="${i===m.index}" ${blocked?'disabled':''}>${esc(q.name)}${i===m.draft.skillTree.selectedPreset?' · 当前':''}</button>`).join('')}</nav><div class="treeBranches">${groups.map(g=>`<section class="treeBranch treeBranch-${g.id}" aria-label="${g.name}"><h3>${g.name}</h3><div class="treeNodes">${g.ids.map(card).join('')}</div></section>`).join('')}</div><div class="treeSlots">${['active','passive'].map(kind=>`<section class="treeSlotSection treeSlotSection-${kind}"><h3>${kind==='active'?'主动技能':'被动技能'}</h3><p>${kind==='active'?'按 1 → 4 的优先级释放':'装入后生效'}</p>${p[kind].map((value,i)=>`<div class="treeSlot treeSlot-${kind}">${renderSkillPixelIcon(value)}<label class="treeSlotChoice"><span>${kind==='active'?'主动':'被动'} ${i+1}</span><select aria-label="${kind==='active'?'主动':'被动'}${i+1}技能" data-tree-slot="${kind}" data-tree-index="${i}" ${blocked||m.conflict?'disabled':''}><option value="">留空</option>${D.nodes.filter(n=>n.kind===kind&&p.unlocked.includes(n.id)).map(n=>`<option value="${n.id}" ${value===n.id?'selected':''} ${p[kind].includes(n.id)&&value!==n.id?'disabled':''}>${esc(n.name)}</option>`).join('')}</select></label>${kind==='active'?`<label class="treeSlotCondition"><span>释放条件</span><select aria-label="主动${i+1}释放条件" data-tree-condition="${i}" ${blocked||m.conflict?'disabled':''}>${choices.map(([id,label])=>`<option value="${id}" ${p.conditions[i]===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}</div>`).join('')}</section>`).join('')}</div>${m.refund?`<aside class="treeReview"><h3>确认退还 ${m.refund.points} 点？</h3><p>将退还：${esc(names(m.refund.ids))}。相关主动/被动将出槽，不自动替补。</p><button data-tree-action="refund-confirm" ${blocked?'disabled':''}>确认退还至草稿</button><button data-tree-action="refund-cancel">取消退款</button></aside>`:''}<footer><button data-tree-action="reset" ${blocked||m.conflict?'disabled':''}>免费重置本方案</button><button data-tree-action="cancel" ${m.busy?'disabled':''}>取消草稿</button>${commitButton()}</footer></section>`;
}
export function mountSkillTree(host,adapter){let disposed=false,m;
 const reset=()=>{const live=adapter.getState(),draft=structuredClone(live);if(!normalizeSkillTree(draft,D))throw Error('invalid skill tree');m={baseState:structuredClone(live),draft,index:draft.skillTree.selectedPreset,beforeTree:structuredClone(live.skillTree??null),busy:false,blocked:false,activationAllowed:adapter.canActivate!==false,error:'',refund:null,activationReview:false};};
 let lastLiveKey='';
 const syncLive=()=>{const live=adapter.getState();m.blocked=!!live.running||!!live.dungeonRun||!!live.activeEncounter&&!live.activeEncounter.done;m.conflict=treeFingerprint(live)!==treeFingerprint(m.baseState);m.inDungeon=!!live.dungeonRun;m.stopRequested=!!live.stopAfterBattle||!!live.stopAfterDungeon;m.draft.running=!!live.running;
 // Level-ups may occur while drafting. Rebase only the earned-point budget; never adopt changed allocations.
 if(!m.conflict){m.baseState.level=live.level;m.draft.level=live.level;}
 lastLiveKey=JSON.stringify([live.level,m.blocked,!!live.dungeonRun,!!live.stopAfterBattle,!!live.stopAfterDungeon,treeFingerprint(live)]);};
 const paint=()=>{if(disposed)return;syncLive();host.innerHTML=renderSkillTree(m);};
 const refresh=()=>{if(disposed)return;const live=adapter.getState(),blocked=!!live.running||!!live.dungeonRun||!!live.activeEncounter&&!live.activeEncounter.done,key=JSON.stringify([live.level,blocked,!!live.dungeonRun,!!live.stopAfterBattle,!!live.stopAfterDungeon,treeFingerprint(live)]);if(key!==lastLiveKey)paint();};
 const changeDraft=fn=>{const next=structuredClone(m.draft);fn(next.skillTree.presets[m.index]);if(!validSkillTree(next,D)){m.error='配置无效：请检查前置、点数与重复技能';return false;}m.draft=next;m.error='';m.activationReview=false;return true;};
 const refund=ids=>{let set=new Set(ids),p=m.draft.skillTree.presets[m.index];for(let previous=-1;previous!==set.size;){previous=set.size;for(const n of D.nodes)if(p.unlocked.includes(n.id)&&n.requires.some(id=>set.has(id)))set.add(n.id);}const list=p.unlocked.filter(id=>set.has(id));m.refund={ids:list,points:D.nodes.filter(n=>list.includes(n.id)).reduce((a,n)=>a+n.cost,0)};};
 const commit=async activate=>{syncLive();if(m.busy||m.blocked||m.conflict)return;m.busy=true;m.error='';paint();try{const result=await adapter.commit({baseState:structuredClone(m.baseState),beforeTree:structuredClone(m.beforeTree),presets:structuredClone(m.draft.skillTree.presets),activate});if(disposed)return;if(result?.ok){reset();m.error='已保存';}else m.error=result?.reason||'保存失败，草稿保留；未应用变更';}catch{m.error='保存失败，草稿保留；未应用变更';}finally{m.busy=false;paint();}};
 const click=async ev=>{const b=ev.target.closest('[data-tree-action]');if(!b||!host.contains(b)||b.disabled)return;const action=b.dataset.treeAction;paint();if(m.busy)return;if(action==='cancel'){reset();adapter.onCancel?.();paint();return;}if(m.conflict)return;
 if(action==='plan'){const i=Number(b.dataset.treeId);if(Number.isInteger(i)&&i>=0&&i<3){m.index=i;m.refund=null;m.activationReview=false;}}
 if(action==='node'){const n=D.nodes.find(n=>n.id===b.dataset.treeId);if(n){if(m.draft.skillTree.presets[m.index].unlocked.includes(n.id))refund([n.id]);else changeDraft(p=>p.unlocked.push(n.id));}}
 if(action==='reset')refund([...m.draft.skillTree.presets[m.index].unlocked]);
 if(action==='refund-cancel')m.refund=null;
 if(action==='refund-confirm'&&m.refund){const ids=m.refund.ids;changeDraft(p=>{p.unlocked=p.unlocked.filter(id=>!ids.includes(id));p.active=p.active.map((id,i)=>{if(ids.includes(id)){p.conditions[i]='always';return null;}return id;});p.passive=p.passive.map(id=>ids.includes(id)?null:id);});m.refund=null;}
 if(action==='activate-cancel')m.activationReview=false;
 if(action==='commit'&&!m.refund)await commit(false);if(action==='activate-review'&&m.activationAllowed&&!m.refund&&m.draft.skillTree.mode!=='active')m.activationReview=true;
 if(action==='activate-confirm'&&m.activationReview)await commit(true);paint();};
 const change=ev=>{const t=ev.target;syncLive();if(m.busy||m.conflict||!host.contains(t))return;const kind=t.dataset.treeSlot,index=Number(t.dataset.treeIndex);if(['active','passive'].includes(kind)&&Number.isInteger(index)&&index>=0&&index<(kind==='active'?4:2))changeDraft(p=>p[kind][index]=t.value||null);if(t.dataset.treeCondition!==undefined){const i=Number(t.dataset.treeCondition);if(Number.isInteger(i)&&i>=0&&i<4&&choices.some(([id])=>id===t.value))changeDraft(p=>p.conditions[i]=t.value);}paint();};
 reset();paint();host.addEventListener('click',click);host.addEventListener('change',change);return {refresh,getDraft:()=>structuredClone(m.draft),dispose(){disposed=true;host.removeEventListener?.('click',click);host.removeEventListener?.('change',change);}};
}
